<?php require_once __DIR__.'/includes/functions.php';require_role(['registrar','teacher']);$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');if(current_user()['role']==='teacher'){ $uid=(int)current_user()['id']; $s=$conn->prepare("SELECT a.attendance_date,a.time_in,a.status,st.student_code,CONCAT(st.first_name,' ',st.last_name) student,sub.subject_code FROM attendance a JOIN students st ON st.id=a.student_id LEFT JOIN subjects sub ON sub.id=a.subject_id JOIN teachers t ON t.id=a.teacher_id WHERE a.attendance_date BETWEEN ? AND ? AND t.user_id=? ORDER BY a.attendance_date DESC,a.time_in DESC"); $s->bind_param('ssi',$from,$to,$uid); } else { $s=$conn->prepare("SELECT a.attendance_date,a.time_in,a.status,st.student_code,CONCAT(st.first_name,' ',st.last_name) student,sub.subject_code FROM attendance a JOIN students st ON st.id=a.student_id LEFT JOIN subjects sub ON sub.id=a.subject_id WHERE a.attendance_date BETWEEN ? AND ? ORDER BY a.attendance_date DESC,a.time_in DESC"); $s->bind_param('ss',$from,$to); } $s->execute();$rows=$s->get_result();include 'includes/header.php';?>
<div class="d-flex justify-content-between mb-3"><h3>Attendance Reports</h3><button class="btn btn-primary no-print" onclick="window.print()">Print Report</button></div><div class="panel"><form class="row g-2 mb-3 no-print"><div class="col-md-4"><label class="form-label">From</label><input class="form-control" type="date" name="from" value="<?=e($from)?>"></div><div class="col-md-4"><label class="form-label">To</label><input class="form-control" type="date" name="to" value="<?=e($to)?>"></div><div class="col-md-4 align-self-end"><button class="btn btn-primary">Filter</button></div></form><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Student ID</th><th>Name</th><th>Subject</th><th>Time In</th><th>Status</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['attendance_date'])?></td><td><?=e($r['student_code'])?></td><td><?=e($r['student'])?></td><td><?=e($r['subject_code']??'General')?></td><td><?=e($r['time_in'])?></td><td><?=e($r['status'])?></td></tr><?php endwhile;?></tbody></table></div></div><?php include 'includes/footer.php';?>
